<?php
/**
 * PyHP transpiler — PyHP AST -> standalone PHP 8 source.
 *
 * The generated file requires src/runtime.php and runs natively via `php`.
 * Values keep the exact PyHP data model (PyList/PyDict objects, PyHP errors,
 * arenas), so programs behave the same as under the interpreter.
 *
 * Known v1 limitations (documented in README):
 *  - classes must be declared at top level in compiled mode
 *  - property type annotations are enforced on construction; later external
 *    writes to obj.prop are not type-checked in compiled mode
 */

require_once __DIR__ . '/runtime.php';

class PyHPTranspiler
{
    private array $classNames = [];      // PyHP name => ['ext' => ?name]  (main file)
    private array $topFuncs = [];        // top-level function names         (main file)
    private array $scopeStack = [];      // each: ['assigned' => string[], 'types' => [name=>type], 'local' => [name=>true]]
    private array $unitVars = [];        // ns => [name => true]: unit-level (top-level) variable names
    private array $varClass = [];        // ns => [varName => [requireSpec, className]]
    private array $unitTypes = [];       // ns => [name => type]: declared types of unit-level vars
    private bool $atUnitTop = true;      // emitting unit top-level statements (not inside a function)
    private int $tmpN = 0;
    private int $indent = 0;
    private string $outFile;
    private ?string $curRet = null;      // current function return annotation
    private string $curFnLabel = '<main>'; // current function display name
    private ?string $curClass = null;    // current class being emitted
    private array $classPropTypes = [];  // PyHP name => [prop => type] (resolved incl. inherited)
    private string $ns = '';             // '' for main file, 'mN_' while emitting a module
    private array $modFuncs = [];        // ns => [name => true]
    private array $modClasses = [];      // ns => [name => ['ext' => ?name]]
    private array $modPropTypes = [];    // ns => [name => [prop => type]]
    private array $pendingMods = [];     // generated PHP for module functions/classes
    private array $modCache = [];        // realpath => module id
    private array $modStack = [];        // require chain (cycle detection)
    private ?string $sourceDir = null;   // dir of the file being transpiled
    private array $cppExports = [];      // native export name => true (compile-time known)
    private int $cppIdN = 0;

    /** Point the transpiler at the source file so require() resolves
     *  relative paths and vendor packages against it. */
    public function setSourceFile(string $file): void {
        $rp = realpath($file);
        $this->sourceDir = $rp !== false ? dirname($rp) : dirname($file);
    }

    private function fnPhp(string $n): string  { return 'pyhp_fn_' . $this->ns . $n; }
    private function clsPhp(string $n): string { return 'PyHP_' . $this->ns . $n; }
    private function funcKnown(string $n): bool {
        if ($this->ns !== '') return isset($this->modFuncs[$this->ns][$n]);
        return isset($this->topFuncs[$n]);
    }
    private function clsKnown(string $n): bool {
        if ($this->ns !== '') return isset($this->modClasses[$this->ns][$n]);
        return isset($this->classNames[$n]);
    }
    private function propTypeOf(string $cls, string $prop): ?string {
        if ($this->ns !== '') return $this->modPropTypes[$this->ns][$cls][$prop] ?? null;
        return $this->classPropTypes[$cls][$prop] ?? null;
    }

    public function transpile(array $stmts, string $outFile): string {
        $this->outFile = $outFile;
        $this->pendingMods = [];
        $this->modCache = [];
        $this->modStack = [];
        $this->ns = '';
        $this->prePass($stmts);

        $this->indent = 0;
        $L = [];
        $L[] = '<?php';
        $L[] = '// Generated by PyHP ' . PYHP_VERSION . ' transpiler — do not edit by hand.';
        $L[] = 'declare(strict_types=1);';
        $L[] = 'require_once ' . $this->runtimePath() . ';';
        $L[] = 'if (!isset($GLOBALS[\'__pyhp_argv\'])) { $GLOBALS[\'__pyhp_argv\'] = array_slice($argv ?? [], 1); }';
        $L[] = '';
        $prologue = count($L);
        $this->scopeStack = [['assigned' => [], 'types' => []]];
        $this->unitVars[''] = $this->collectUnitVars($stmts);
        $this->atUnitTop = true;
        foreach ($stmts as $s) { $this->emitStmt($s, $L); }
        if (count($this->pendingMods) > 0) {
            array_splice($L, $prologue, 0, $this->pendingMods);
        }
        return implode("\n", $L) . "\n";
    }

    /* ================================================================ */
    /* pre-pass                                                         */
    /* ================================================================ */

    private function prePass(array $stmts): void {
        $this->prePassStmts($stmts, true);
        // resolve property types including inherited
        foreach ($this->classNames as $name => $def) {
            $chain = [];
            $c = $name;
            while ($c !== null && isset($this->classNames[$c])) {
                array_unshift($chain, $c);
                $c = $this->classNames[$c]['ext'];
            }
            $resolved = [];
            foreach ($chain as $cn) {
                foreach ($this->classPropTypes[$cn] ?? [] as $p => $t) { $resolved[$p] = $t; }
            }
            $this->classPropTypes[$name] = $resolved;
        }
    }

    /** Collect classes and (conditionally-defined) top-level functions,
     *  including those declared inside top-level control-flow blocks. */
    private function prePassStmts(array $stmts, bool $top): void {
        foreach ($stmts as $s) {
            if ($top && $s['k'] === 'Class') {
                $props = [];
                foreach ($s['members'] as $m) {
                    if ($m['k'] === 'VarDecl' && $m['type'] !== null && $m['type'] !== 'var') {
                        $props[$m['name']] = $m['type'];
                    }
                }
                if ($this->ns === '') {
                    $this->classNames[$s['name']] = ['ext' => $s['ext']];
                    $this->classPropTypes[$s['name']] = $props;
                } else {
                    $this->modClasses[$this->ns][$s['name']] = ['ext' => $s['ext']];
                    $this->modPropTypes[$this->ns][$s['name']] = $props;
                }
            } elseif ($top && $s['k'] === 'Func' && $s['name'] !== null) {
                if ($this->ns === '') { $this->topFuncs[$s['name']] = true; }
                else { $this->modFuncs[$this->ns][$s['name']] = true; }
            }
            if ($top) {
                switch ($s['k']) {
                    case 'If':
                        foreach ($s['branches'] as [, $body]) { $this->prePassStmts($body['stmts'], true); }
                        if ($s['else'] !== null) $this->prePassStmts($s['else']['stmts'], true);
                        break;
                    case 'While': case 'DoWhile':
                        $this->prePassStmts($s['body']['stmts'], true);
                        break;
                    case 'For':
                        $this->prePassStmts($s['body']['stmts'], true);
                        break;
                    case 'Foreach':
                        $this->prePassStmts($s['body']['stmts'], true);
                        break;
                    case 'Try':
                        $this->prePassStmts($s['body']['stmts'], true);
                        foreach ($s['catches'] as $c) { $this->prePassStmts($c['body']['stmts'], true); }
                        if ($s['finally'] !== null) $this->prePassStmts($s['finally']['stmts'], true);
                        break;
                    case 'Block':
                        $this->prePassStmts($s['stmts'], true);
                        break;
                }
            }
        }
    }

    private function runtimePath(): string {
        $runtime = realpath(__DIR__ . '/runtime.php');
        $dir = realpath(dirname($this->outFile) ?: '.');
        if ($runtime !== false && $dir !== false && str_starts_with($runtime, $dir . '/')) {
            // output dir is an ancestor of the PyHP install: emit a __DIR__-relative
            // require, but keep the '/' separator (__DIR__ alone has no trailing slash)
            return '__DIR__ . ' . var_export('/' . substr($runtime, strlen($dir) + 1), true);
        }
        return var_export($runtime ?: __DIR__ . '/runtime.php', true);
    }

    /* ================================================================ */
    /* scope helpers                                                    */
    /* ================================================================ */

    private function pushScope(): void { $this->scopeStack[] = ['assigned' => [], 'types' => []]; }
    private function popScope(): void { array_pop($this->scopeStack); }
    private function &curScope(): array { return $this->scopeStack[count($this->scopeStack) - 1]; }
    private function markAssigned(string $name): void {
        $scope = &$this->curScope();
        if (!in_array($name, $scope['assigned'], true)) $scope['assigned'][] = $name;
    }
    private function assignedSoFar(): array {
        $scope = $this->curScope();
        return $scope['assigned'];
    }
    private function markLocal(string $name): void {
        $scope = &$this->curScope();
        $scope['local'][$name] = true;
    }
    /** Is $name a unit-level variable visible here (not shadowed by a
     *  parameter or local declaration in an enclosing function scope)? */
    private function isUnitVar(string $name): bool {
        if (!isset($this->unitVars[$this->ns][$name])) return false;
        foreach ($this->scopeStack as $sc) {
            if (isset($sc['local'][$name])) return false;
        }
        return true;
    }
    /** Compiled read expression for a unit var in a module unit, or null.
     *  Main-unit vars need no rewrite (a `global` declaration is injected). */
    private function unitVarRead(string $name): ?string {
        if ($this->ns === '' || !$this->isUnitVar($name)) return null;
        return 'pyhp_unit_get(' . var_export(rtrim($this->ns, '_'), true) . ', ' . var_export($name, true) . ')';
    }
    /** Compiled write target for a unit var in a module unit, or null. */
    private function unitVarWrite(string $name): ?string {
        if ($this->ns === '' || !$this->isUnitVar($name)) return null;
        return "\$GLOBALS['__pyhp_unit_" . rtrim($this->ns, '_') . "']['{$name}']";
    }
    /** `global $a, $b;` declaration for the main unit's top-level vars. */
    private function globalDecl(array $skip): ?string {
        if ($this->ns !== '') return null;
        $names = array_diff(array_keys($this->unitVars[''] ?? []), $skip);
        if (count($names) === 0) return null;
        return 'global ' . implode(', ', array_map(fn($n) => '$' . $n, $names)) . ';';
    }
    private function setVarType(string $name, string $type): void {
        $scope = &$this->curScope();
        if ($type !== null && $type !== 'var') $scope['types'][$name] = $type;
        else unset($scope['types'][$name]);
    }
    private function varType(string $name): ?string {
        $scope = $this->curScope();
        return $scope['types'][$name] ?? null;
    }
    private function tmp(): string { return '$__pyhp_t' . (++$this->tmpN); }

    private function paramNames(array $params): array {
        $names = [];
        foreach ($params as $p) $names[] = $p['name'];
        return $names;
    }

    /* ================================================================ */
    /* statement emission                                               */
    /* ================================================================ */

    private function w(array &$L, string $line): void {
        $L[] = str_repeat('    ', $this->indent) . $line;
    }

    private function emitStmt(array $s, array &$L): void {
        switch ($s['k']) {
            case 'Expr':
                if ($s['e']['k'] === 'Assign') { $this->emitAssignStmt($s['e'], $L); return; }
                if ($s['e']['k'] === 'Post') { $this->w($L, $this->emitPost($s['e']) . ';'); return; }
                $this->w($L, $this->emitExpr($s['e']) . ';');
                return;
            case 'VarDecl':
                $this->emitVarDecl($s, $L);
                return;
            case 'Func':
                if ($s['name'] === null) { $this->w($L, $this->emitExpr($s) . ';'); return; }
                if (count($this->scopeStack) === 1) {
                    $this->emitTopFunction($s, $L);
                } else {
                    $this->emitNestedFunction($s, $L);
                }
                return;
            case 'Class':
                if (count($this->scopeStack) !== 1) {
                    throw new PyHPSyntaxError("line {$s['line']}: classes must be declared at top level in compiled mode (use the interpreter for local classes)");
                }
                $this->emitClass($s, $L);
                return;
            case 'If':
                $first = true;
                foreach ($s['branches'] as [$cond, $body]) {
                    if ($first) {
                        $this->w($L, 'if (pyhp_truthy(' . $this->emitExpr($cond) . ')) {');
                        $first = false;
                    } else {
                        $this->w($L, '} elseif (pyhp_truthy(' . $this->emitExpr($cond) . ')) {');
                    }
                    $this->indent++;
                    $this->emitStmt($body, $L);
                    $this->indent--;
                }
                if ($s['else'] !== null) {
                    $this->w($L, '} else {');
                    $this->indent++;
                    $this->emitStmt($s['else'], $L);
                    $this->indent--;
                }
                $this->w($L, '}');
                return;
            case 'While':
                $this->w($L, 'while (pyhp_truthy(' . $this->emitExpr($s['cond']) . ')) {');
                $this->indent++;
                $this->emitStmt($s['body'], $L);
                $this->indent--;
                $this->w($L, '}');
                return;
            case 'DoWhile':
                $this->w($L, 'do {');
                $this->indent++;
                $this->emitStmt($s['body'], $L);
                $this->indent--;
                $this->w($L, '} while (pyhp_truthy(' . $this->emitExpr($s['cond']) . '));');
                return;
            case 'For': {
                $init = $s['init'] === null ? '' : $this->emitInitInline($s['init']);
                $cond = $s['cond'] === null ? '' : 'pyhp_truthy(' . $this->emitExpr($s['cond']) . ')';
                $updates = [];
                if ($s['update'] !== null) { $this->collectUpdates($s['update'], $updates); }
                $updStr = implode(', ', array_map(fn($u) => $this->emitUpdatePart($u), $updates));
                $this->w($L, "for ({$init}; {$cond}; {$updStr}) {");
                $this->indent++;
                $this->emitStmt($s['body'], $L);
                $this->indent--;
                $this->w($L, '}');
                return;
            }
            case 'Foreach': {
                $iter = $this->emitExpr($s['iter']);
                $r1 = $this->unitVarWrite($s['var1']) ?? "\${$s['var1']}";
                if ($s['var2'] !== null) {
                    $r2 = $this->unitVarWrite($s['var2']) ?? "\${$s['var2']}";
                    $this->markAssigned($s['var1']); $this->markAssigned($s['var2']);
                    if (!$this->atUnitTop) { $this->markLocal($s['var1']); $this->markLocal($s['var2']); }
                    $this->w($L, "foreach (pyhp_iter({$iter}) as {$r1} => {$r2}) {");
                } else {
                    $this->markAssigned($s['var1']);
                    if (!$this->atUnitTop) $this->markLocal($s['var1']);
                    $this->w($L, "foreach (pyhp_iter({$iter}) as {$r1}) {");
                }
                $this->indent++;
                $this->emitStmt($s['body'], $L);
                $this->indent--;
                $this->w($L, '}');
                return;
            }
            case 'Try':
                $this->emitTry($s, $L);
                return;
            case 'Throw':
                $this->emitThrow($s, $L);
                return;
            case 'Return':
                if ($this->curRet !== null) {
                    $v = $s['e'] === null ? 'null' : $this->emitExpr($s['e']);
                    $this->w($L, "return pyhp_check_type({$v}, '{$this->curRet}', '{$this->curFnLabel}() return');");
                } else {
                    $this->w($L, 'return ' . ($s['e'] === null ? '' : $this->emitExpr($s['e'])) . ';');
                }
                return;
            case 'Break':
                $this->w($L, 'break;');
                return;
            case 'Continue':
                $this->w($L, 'continue;');
                return;
            case 'Echo': {
                $parts = array_map(fn($a) => 'pyhp_tostr(' . $this->emitExpr($a) . ')', $s['args']);
                $this->w($L, 'echo ' . (implode(', ', $parts) ?: "''") . ';');
                return;
            }
            case 'Block':
                $this->w($L, '{');
                $this->indent++;
                foreach ($s['stmts'] as $st) { $this->emitStmt($st, $L); }
                $this->indent--;
                $this->w($L, '}');
                return;
            case 'Cpp':
                $id = 'c' . (++$this->cppIdN);
                foreach ($s['exports'] as $e) { $this->cppExports[$e['name']] = true; }
                $this->w($L, 'pyhp_cpp_register(' . var_export($id, true) . ', ' . var_export($s['code'], true) . ');');
                return;
        }
        throw new PyHPSyntaxError("line {$s['line']}: unsupported statement '{$s['k']}' in compiled mode");
    }

    /** Static pass: every variable assigned at the unit's top level (module
     *  state). Walks top-level control flow but never enters functions or
     *  classes — those have their own scopes. */
    private function collectUnitVars(array $stmts): array {
        $names = [];
        $walk = function (array $ss) use (&$walk, &$names): void {
            foreach ($ss as $s) {
                switch ($s['k']) {
                    case 'VarDecl':
                        $names[$s['name']] = true;
                        if ($s['init'] !== null) $this->collectClassBinding($s['name'], $s['init']);
                        break;
                    case 'Expr':
                        if ($s['e']['k'] === 'Assign' && $s['e']['op'] === '=' && $s['e']['target']['k'] === 'Var') {
                            $this->collectClassBinding($s['e']['target']['name'], $s['e']['value']);
                        }
                        $this->collectVarTargets($s['e'], $names); break;
                    case 'If':
                        foreach ($s['branches'] as [$cond, $body]) { $walk($body['stmts']); }
                        if ($s['else'] !== null) $walk($s['else']['stmts']);
                        break;
                    case 'While': case 'DoWhile':
                        $walk($s['body']['stmts']); break;
                    case 'For':
                        if ($s['init'] !== null) {
                            if ($s['init']['k'] === 'VarDecl') $names[$s['init']['name']] = true;
                            elseif ($s['init']['k'] === 'Expr') $this->collectVarTargets($s['init']['e'], $names);
                        }
                        if ($s['update'] !== null) { $this->collectVarTargets($s['update'], $names); }
                        $walk($s['body']['stmts']); break;
                    case 'Foreach':
                        $names[$s['var1']] = true;
                        if ($s['var2'] !== null) $names[$s['var2']] = true;
                        $walk($s['body']['stmts']); break;
                    case 'Try':
                        $walk($s['body']['stmts']);
                        foreach ($s['catches'] as $c) { $walk($c['body']['stmts']); }
                        break;
                }
            }
        };
        $walk($stmts);
        return $names;
    }

    /** Expression-level assignment targets (a = .., i++, for-updates). */
    private function collectVarTargets(array $e, array &$names): void {
        switch ($e['k']) {
            case 'Assign':
                if ($e['target']['k'] === 'Var') $names[$e['target']['name']] = true;
                $this->collectVarTargets($e['value'], $names);
                break;
            case 'Post':
                if ($e['e']['k'] === 'Var') $names[$e['e']['name']] = true;
                break;
            case 'Bin':
                if ($e['op'] === ',') { $this->collectVarTargets($e['l'], $names); $this->collectVarTargets($e['r'], $names); }
                break;
        }
    }

    /** Record `S = require("spec").Cls` — a class imported from another
     *  module, usable as a parent in `class X extends S`. */
    private function collectClassBinding(string $var, array $value): void {
        if ($value['k'] !== 'Member' || $value['obj']['k'] !== 'Call') return;
        $call = $value['obj'];
        if (($call['callee']['k'] ?? '') !== 'Var' || $call['callee']['name'] !== 'require') return;
        if (count($call['args']) !== 1 || $call['args'][0]['k'] !== 'Str') return;
        $this->varClass[$this->ns][$var] = [$call['args'][0]['v'], $value['name']];
    }

    /** Resolve a var-held parent class (from `S = require(...).Cls`) to the
     *  compiled PHP class name of the module that exports it. */
    private function resolveVarClassParent(string $var, int $line): ?string {
        if (!isset($this->varClass[$this->ns][$var])) return null;
        [$spec, $clsName] = $this->varClass[$this->ns][$var];
        $base = $this->sourceDir ?? (getcwd() ?: '.');
        $path = pyhp_resolve_module($spec, $base);
        if ($path === null) {
            throw new PyHPSyntaxError("line {$line}: ModuleNotFoundError: cannot find module '{$spec}'");
        }
        $modId = $this->compileModule($path, $spec, $line);   // compiles on demand
        $modNs = $modId . '_';
        if (!isset($this->modClasses[$modNs][$clsName])) {
            throw new PyHPSyntaxError("line {$line}: module '{$spec}' does not export a class named '{$clsName}'");
        }
        return $modNs . $clsName;
    }

    private function emitVarDecl(array $s, array &$L): void {
        $name = $s['name'];
        $this->markAssigned($name);
        $type = $s['type'];
        $this->setVarType($name, $type);
        $this->unitTypes[$this->ns][$name] = $type;
        if (!$this->atUnitTop) $this->markLocal($name);
        if ($this->atUnitTop && $this->ns !== '') {
            // module-level state lives in the unit's GLOBALS bucket so the
            // module's plain PHP functions can read and write it
            $ref = $this->unitVarWrite($name);
            if ($s['init'] !== null) {
                $v = $this->emitExpr($s['init']);
                $this->w($L, $this->typedWrap($ref, $v, $type, $name) . ';');
            } else {
                $this->w($L, "{$ref} = null;");
            }
            return;
        }
        if ($s['init'] !== null) {
            $v = $this->emitExpr($s['init']);
            $this->w($L, $this->typedWrap("\${$name}", $v, $type, $name) . ';');
        } else {
            $this->w($L, "\${$name} = null;");
        }
    }

    private function typedWrap(string $varExpr, string $valueExpr, ?string $type, string $name): string {
        if ($type !== null && $type !== 'var') {
            return "{$varExpr} = pyhp_check_type({$valueExpr}, '{$type}', '{$name}');";
        }
        return "{$varExpr} = {$valueExpr};";
    }

    /** for-init / nested-function assignment handling without semicolon */
    private function emitInitInline(array $s): string {
        if ($s['k'] === 'VarDecl') {
            $name = $s['name'];
            $this->markAssigned($name);
            $this->setVarType($name, $s['type']);
            $this->unitTypes[$this->ns][$name] = $s['type'];
            if (!$this->atUnitTop) $this->markLocal($name);
            if ($this->atUnitTop && $this->ns !== '') {
                $ref = $this->unitVarWrite($name);
                if ($s['init'] !== null) {
                    $v = $this->emitExpr($s['init']);
                    return rtrim($this->typedWrap($ref, $v, $s['type'], $name), ';');
                }
                return "{$ref} = null";
            }
            if ($s['init'] !== null) {
                $v = $this->emitExpr($s['init']);
                return rtrim($this->typedWrap("\${$name}", $v, $s['type'], $name), ';');
            }
            return "\${$name} = null";
        }
        if ($s['k'] === 'Expr') {
            if ($s['e']['k'] === 'Assign') { return rtrim($this->emitAssignCode($s['e']), ';'); }
            if ($s['e']['k'] === 'Post') { return $this->emitPost($s['e']); }
            return $this->emitExpr($s['e']);
        }
        throw new PyHPSyntaxError("line {$s['line']}: unsupported for-init statement");
    }

    private function collectUpdates(array $e, array &$out): void {
        if ($e['k'] === 'Bin' && $e['op'] === ',') {
            $this->collectUpdates($e['l'], $out);
            $this->collectUpdates($e['r'], $out);
            return;
        }
        $out[] = $e;
    }

    private function emitUpdatePart(array $e): string {
        if ($e['k'] === 'Post') return $this->emitPost($e);
        if ($e['k'] === 'Assign') return rtrim($this->emitAssignCode($e), ';');
        return $this->emitExpr($e);
    }

    /* ---------------- assignment statements ---------------- */

    private function emitAssignStmt(array $e, array &$L): void {
        $this->w($L, $this->emitAssignCode($e) . ';');
    }

    private function emitAssignCode(array $e): string {
        $t = $e['target'];
        $op = $e['op'];
        if ($t['k'] === 'Var') {
            $name = $t['name'];
            $this->markAssigned($name);
            $ref = $this->unitVarWrite($name);
            $type = $this->varType($name) ?? ($ref !== null ? ($this->unitTypes[$this->ns][$name] ?? null) : null);
            $varExpr = $ref ?? "\${$name}";
            if ($op === '=') {
                $v = $this->emitExpr($e['value']);
                return $this->typedWrapWithoutSemi($varExpr, $v, $type, $name);
            }
            $v = $this->emitExpr($e['value']);
            if ($type !== null && $type !== 'var') {
                $expr = $this->compoundExpr($op, $varExpr, $v);
                return "{$varExpr} = pyhp_check_type({$expr}, '{$type}', '{$name}')";
            }
            return $this->compoundAssign($op, $varExpr, $v);
        }
        if ($t['k'] === 'Idx') {
            $obj = $this->emitExpr($t['obj']);
            $idx = $this->emitExpr($t['idx']);
            $v = $this->emitExpr($e['value']);
            if ($op === '=') return "pyhp_set({$obj}, {$idx}, {$v})";
            $expr = $this->compoundExpr($op, "pyhp_get({$obj}, {$idx})", $v);
            return "pyhp_set({$obj}, {$idx}, {$expr})";
        }
        if ($t['k'] === 'Member') {
            $name = $t['name'];
            $v = $this->emitExpr($e['value']);
            if ($t['obj']['k'] === 'This') {
                $ptype = $this->curClass !== null ? $this->propTypeOf($this->curClass, $name) : null;
                if ($op === '=') {
                    if ($ptype !== null && $ptype !== 'var') {
                        return "\$this->{$name} = pyhp_check_type({$v}, '{$ptype}', '{$name}')";
                    }
                    return "\$this->{$name} = {$v}";
                }
                $expr = $this->compoundExpr($op, "\$this->{$name}", $v);
                if ($ptype !== null && $ptype !== 'var') {
                    return "\$this->{$name} = pyhp_check_type({$expr}, '{$ptype}', '{$name}')";
                }
                return "\$this->{$name} = {$expr}";
            }
            if ($t['obj']['k'] === 'Var') {
                $base = '$' . $t['obj']['name'];
                if ($op === '=') return "{$base}->{$name} = {$v}";
                return "{$base}->{$name} = " . $this->compoundExpr($op, "{$base}->{$name}", $v);
            }
            throw new PyHPSyntaxError("line {$e['line']}: can only assign to properties of 'this' or a variable in compiled mode");
        }
        throw new PyHPSyntaxError("line {$e['line']}: invalid assignment target in compiled mode");
    }

    private function typedWrapWithoutSemi(string $varExpr, string $valueExpr, ?string $type, string $name): string {
        if ($type !== null && $type !== 'var') {
            return "{$varExpr} = pyhp_check_type({$valueExpr}, '{$type}', '{$name}')";
        }
        return "{$varExpr} = {$valueExpr}";
    }

    private function compoundAssign(string $op, string $varExpr, string $valueExpr): string {
        // route through the pyhp_* helpers so string `+=` concat matches the interpreter
        return $varExpr . ' = ' . $this->compoundExpr($op, $varExpr, $valueExpr);
    }

    private function compoundExpr(string $op, string $old, string $value): string {
        return match ($op) {
            '+=' => "pyhp_add({$old}, {$value})",
            '-=' => "pyhp_sub({$old}, {$value})",
            '*=' => "pyhp_mul({$old}, {$value})",
            '/=' => "pyhp_div({$old}, {$value})",
            '%=' => "pyhp_mod({$old}, {$value})",
            '**=' => "pyhp_pow({$old}, {$value})",
            '&=' => "pyhp_bitand({$old}, {$value})",
            '|=' => "pyhp_bitor({$old}, {$value})",
            '^=' => "pyhp_bitxor({$old}, {$value})",
            '<<=' => "pyhp_lshift({$old}, {$value})",
            '>>=' => "pyhp_rshift({$old}, {$value})",
            default => throw new PyHPSyntaxError("unknown compound operator '{$op}'"),
        };
    }

    private function emitPost(array $e): string {
        $name = $e['e']['name'];
        $this->markAssigned($name);
        $ref = $this->unitVarWrite($name);
        return ($ref ?? "\${$name}") . $e['op'];
    }

    /* ---------------- try / throw ---------------- */

    private function emitTry(array $s, array &$L): void {
        $this->w($L, 'try {');
        $this->indent++;
        $this->emitStmt($s['body'], $L);
        $this->indent--;
        foreach ($s['catches'] as $c) {
            $phpClass = $this->catchClass($c['type']);
            $this->w($L, "} catch ({$phpClass} \${$c['var']}) {");
            $this->markAssigned($c['var']);
            $this->indent++;
            $this->emitStmt($c['body'], $L);
            $this->indent--;
        }
        if ($s['finally'] !== null) {
            $this->w($L, '} finally {');
            $this->indent++;
            $this->emitStmt($s['finally'], $L);
            $this->indent--;
        }
        $this->w($L, '}');
    }

    private function catchClass(?string $type): string {
        if ($type === null) return 'PyHPError';
        $map = pyhp_error_class_map();
        if (isset($map[$type])) return $map[$type];
        if ($this->clsKnown($type)) return $this->clsPhp($type);
        return 'PyHPError';
    }

    private function emitThrow(array $s, array &$L): void {
        $e = $s['e'];
        if ($e['k'] === 'Call' && $e['callee']['k'] === 'Var') {
            $name = $e['callee']['name'];
            $args = array_map(fn($a) => $this->emitExpr($a), $e['args']);
            $argStr = implode(', ', $args);
            $map = pyhp_error_class_map();
            if (isset($map[$name])) {
                $this->w($L, "throw new {$map[$name]}({$argStr});");
                return;
            }
            if (isset($this->classNames[$name])) {
                $this->w($L, "throw new PyHP_{$name}({$argStr});");
                return;
            }
        }
        $this->w($L, 'throw new PyHPRuntimeError(pyhp_tostr(' . $this->emitExpr($e) . '));');
    }

    /* ---------------- functions ---------------- */

    private function emitParamList(array $params): string {
        // All params are emitted optional (PHP enforces its own required-arg
        // rule otherwise); the prologue below raises PyHPTypeErrors instead.
        $parts = [];
        $restName = null;
        foreach ($params as $p) {
            if ($p['variadic']) { $restName = $p['name']; continue; }
            $parts[] = '$' . $p['name'] . ' = null';
        }
        if ($restName !== null) $parts[] = '...$__pyhp_rest';
        return implode(', ', $parts);
    }

    private function emitPrologue(array $params, string $fnLabel, array &$L): void {
        $nParams = 0;
        foreach ($params as $p) { if (!$p['variadic']) $nParams++; }
        $variadic = false;
        foreach ($params as $p) { if ($p['variadic']) $variadic = true; }
        if (!$variadic) {
            $this->w($L, "if (func_num_args() > {$nParams}) {");
            $this->indent++;
            $this->w($L, "throw new PyHPTypeError(\"{$fnLabel}() takes {$nParams} argument(s), \" . func_num_args() . \" given\");");
            $this->indent--;
            $this->w($L, '}');
        }
        $i = 0;
        foreach ($params as $p) {
            if ($p['variadic']) {
                $this->w($L, "\${$p['name']} = new PyList(\$__pyhp_rest);");
                $this->markAssigned($p['name']);
                break;
            }
            if ($p['def'] !== null) {
                $def = $this->emitExpr($p['def']);
                $this->w($L, "if (func_num_args() <= {$i} || \\PyHPMissing::is(\${$p['name']})) {");
                $this->indent++;
                $this->w($L, $this->typedWrap("\${$p['name']}", $def, $p['type'], $p['name']));
                $this->indent--;
                $this->w($L, '}');
            } else {
                $this->w($L, "if (func_num_args() <= {$i} || \\PyHPMissing::is(\${$p['name']})) {");
                $this->indent++;
                $this->w($L, "throw new PyHPTypeError(\"{$fnLabel}() missing required argument '{$p['name']}'\");");
                $this->indent--;
                $this->w($L, '}');
            }
            if ($p['type'] !== null && $p['type'] !== 'var') {
                $this->w($L, "\${$p['name']} = pyhp_check_type(\${$p['name']}, '{$p['type']}', '{$p['name']}');");
            }
            if ($p['type'] !== null && $p['type'] !== 'var') $this->setVarType($p['name'], $p['type']);
            $this->markAssigned($p['name']);
            $this->markLocal($p['name']);
            $i++;
        }
    }

    private function emitTopFunction(array $s, array &$L): void {
        if (pyhp_ast_has_yield($s['body']['stmts'])) {
            $this->emitGeneratorFunction($s, $L, []);
            return;
        }
        $this->w($L, 'function ' . $this->fnPhp($s['name']) . '(' . $this->emitParamList($s['params']) . ') {');
        $this->indent++;
        $this->pushScope();
        $gd = $this->globalDecl($this->paramNames($s['params']));
        if ($gd !== null) { $this->w($L, $gd); }
        $prevRet = $this->curRet;
        $prevLabel = $this->curFnLabel;
        $this->curRet = $s['ret'];
        $this->curFnLabel = $s['name'];
        $savedTop = $this->atUnitTop;
        $this->atUnitTop = false;
        $this->emitPrologue($s['params'], $s['name'], $L);
        $this->emitStmt($s['body'], $L);
        $this->atUnitTop = $savedTop;
        if ($s['ret'] !== null) {
            $this->w($L, "return pyhp_check_type(null, '{$s['ret']}', '{$s['name']}() return');");
        }
        $this->curRet = $prevRet;
        $this->curFnLabel = $prevLabel;
        $this->popScope();
        $this->indent--;
        $this->w($L, '}');
        $this->w($L, '');
    }

    private function emitNestedFunction(array $s, array &$L): void {
        $name = $s['name'];
        // bind the name first so the closure can capture itself for recursion
        $this->markAssigned($name);
        if (pyhp_ast_has_yield($s['body']['stmts'])) {
            $this->w($L, "\${$name} = " . $this->emitGenClosure($s, [$name]) . ';');
            return;
        }
        $this->w($L, "\${$name} = " . $this->emitClosure($s, [$name]) . ';');
    }

    private function emitClosure(array $s, array $extraSelfRefs = []): string {
        if (pyhp_ast_has_yield($s['body']['stmts'])) {
            return $this->emitGenClosure($s, $extraSelfRefs);
        }
        // captures: everything assigned so far minus this function's own params
        // and minus unit-level vars (those resolve via `global` / the unit bucket)
        $params = $this->paramNames($s['params']);
        $captures = array_values(array_diff(
            $this->assignedSoFar(), $params, $extraSelfRefs,
            array_keys($this->unitVars[$this->ns] ?? [])
        ));
        $useParts = array_map(fn($c) => '&$' . $c, $captures);
        foreach ($extraSelfRefs as $r) { $useParts[] = '&$' . $r; }
        $use = count($useParts) > 0 ? ' use (' . implode(', ', $useParts) . ')' : '';
        $label = $s['name'] ?? '<closure>';
        $body = [];
        $this->pushScope();
        $prevRet = $this->curRet;
        $prevLabel = $this->curFnLabel;
        $this->curRet = $s['ret'];
        $this->curFnLabel = $label;
        $savedTop = $this->atUnitTop;
        $this->atUnitTop = false;
        $gd = $this->globalDecl($params);
        if ($gd !== null) { $this->w($body, $gd); }
        $this->emitPrologue($s['params'], $label, $body);
        foreach ($s['body']['stmts'] as $st) { $this->emitStmt($st, $body); }
        $this->atUnitTop = $savedTop;
        if ($s['ret'] !== null) {
            $this->w($body, "return pyhp_check_type(null, '{$s['ret']}', '{$label}() return');");
        }
        $this->curRet = $prevRet;
        $this->curFnLabel = $prevLabel;
        $this->popScope();
        $inner = implode("\n", array_map(fn($l) => $l === '' ? '' : '    ' . $l, $body));
        return 'function (' . $this->emitParamList($s['params']) . "){$use} {\n" . $inner . "\n}";
    }

    /* ---------------- generators (compiled mode) ----------------
     *
     * A function containing `yield` emits an outer function with the usual
     * prologue (arity/default errors fire at call time, like Python) that
     * returns a PyHPGenerator wrapping an inner PHP generator closure with
     * the real `yield`s. Variables ride PHP's closure capture, so late
     * binding matches the PHP engines exactly. */

    private function emitGeneratorFunction(array $s, array &$L, array $extraSelfRefs): void {
        $this->w($L, 'function ' . $this->fnPhp($s['name']) . '(' . $this->emitParamList($s['params']) . ') {');
        $this->indent++;
        $this->pushScope();
        $gd = $this->globalDecl($this->paramNames($s['params']));
        $prevRet = $this->curRet;
        $this->curRet = null;
        $savedTop = $this->atUnitTop;
        $this->atUnitTop = false;
        $this->emitPrologue($s['params'], $s['name'], $L);
        $useVars = array_merge($this->paramNames($s['params']), $extraSelfRefs);
        $use = count($useVars) > 0 ? ' use (' . implode(', ', array_map(fn($v) => '&$' . $v, $useVars)) . ')' : '';
        $this->w($L, "return new PyHPGenerator((function (){$use} {");
        $this->indent++;
        if ($gd !== null) { $this->w($L, $gd); }
        foreach ($s['body']['stmts'] as $st) { $this->emitStmt($st, $L); }
        $this->indent--;
        $this->w($L, "})(), " . var_export($s['name'], true) . ');');
        $this->atUnitTop = $savedTop;
        $this->curRet = $prevRet;
        $this->popScope();
        $this->indent--;
        $this->w($L, '}');
        $this->w($L, '');
    }

    /** Anonymous/nested generator closure: an outer closure (with the usual
     *  prologue) whose call returns a PyHPGenerator wrapping an inner PHP
     *  generator closure that carries the real `yield`s. */
    private function emitGenClosure(array $s, array $extraSelfRefs = []): string {
        $params = $this->paramNames($s['params']);
        $captures = array_values(array_diff(
            $this->assignedSoFar(), $params, $extraSelfRefs,
            array_keys($this->unitVars[$this->ns] ?? [])
        ));
        $outerUseParts = array_map(fn($c) => '&$' . $c, $captures);
        foreach ($extraSelfRefs as $r) { $outerUseParts[] = '&$' . $r; }
        $outerUse = count($outerUseParts) > 0 ? ' use (' . implode(', ', $outerUseParts) . ')' : '';
        $label = $s['name'] ?? '<generator>';
        $body = [];
        $this->pushScope();
        $prevRet = $this->curRet;
        $this->curRet = null;
        $savedTop = $this->atUnitTop;
        $this->atUnitTop = false;
        $gd = $this->globalDecl($params);
        if ($gd !== null) { $this->w($body, $gd); }
        $this->emitPrologue($s['params'], $label, $body);
        $innerUse = array_map(fn($c) => '&$' . $c, $captures);
        foreach ($params as $p) { $innerUse[] = '$' . $p; }   // params by value into the gen
        $innerUseStr = count($innerUse) > 0 ? ' use (' . implode(', ', $innerUse) . ')' : '';
        $this->w($body, "return new PyHPGenerator((function (){$innerUseStr} {");
        $this->indent++;
        foreach ($s['body']['stmts'] as $st) { $this->emitStmt($st, $body); }
        $this->indent--;
        $this->w($body, "})(), " . var_export($label, true) . ');');
        $this->atUnitTop = $savedTop;
        $this->curRet = $prevRet;
        $this->popScope();
        $inner = implode("\n", array_map(fn($l) => $l === '' ? '' : '    ' . $l, $body));
        return 'function (' . $this->emitParamList($s['params']) . "){$outerUse} {\n" . $inner . "\n}";
    }

    /* ---------------- classes ---------------- */

    private function emitClass(array $s, array &$L): void {
        $name = $s['name'];
        $phpName = $this->clsPhp($name);
        $ext = '';
        if ($s['ext'] !== null) {
            $map = pyhp_error_class_map();
            if ($this->clsKnown($s['ext'])) {
                $ext = ' extends ' . $this->clsPhp($s['ext']);
            } elseif (isset($map[$s['ext']])) {
                $ext = ' extends ' . $map[$s['ext']];
            } elseif (($parentPhp = $this->resolveVarClassParent($s['ext'], $s['line'])) !== null) {
                // `class X extends S` where S = require("mod.pyh").Cls
                $ext = ' extends PyHP_' . $parentPhp;
            } elseif ($this->ns !== '') {
                throw new PyHPSyntaxError("line {$s['line']}: module classes cannot extend classes from other files");
            }
        }
        $this->w($L, "class {$phpName}{$ext} {");
        $this->indent++;
        $this->w($L, 'const PYHP_CLASS = ' . var_export($name, true) . ';');
        $this->curClass = $name;

        $ctorBody = [];
        $ctorParams = null;
        $ctorHasBody = false;
        $hasCtor = false;
        $strMethod = null;

        foreach ($s['members'] as $m) {
            if ($m['k'] === 'VarDecl') {
                $this->w($L, 'public $' . $m['name'] . ';');
                // default value assignment happens in the constructor
                if ($m['init'] !== null) {
                    $v = $this->emitExprScopeIsolated($m['init']);
                    $t = $m['type'];
                    $ctorBody[] = $this->typedWrapWithoutSemi("\$this->{$m['name']}", $v, $t, $m['name']) . ';';
                }
            } elseif ($m['k'] === 'Func') {
                $mname = $m['name'];
                if ($mname === '__construct' || $mname === '__init') {
                    if ($mname === '__construct' || !$hasCtor) {
                        $ctorParams = $m['params'];
                        $ctorHasBody = count($m['body']['stmts']) > 0;
                        $ctorBodyStmts = $m['body'];
                        $hasCtor = true;
                    }
                } elseif ($mname === '__str__' || $mname === '__toString') {
                    $strMethod = $m;
                } else {
                    $this->emitMethod($m, $L);
                }
            }
        }

        // constructor: emit only when the class defines one or has property
        // defaults; otherwise inherit the parent's constructor untouched
        $params = $ctorParams ?? [];
        $phpRet = '';
        if ($hasCtor || count($ctorBody) > 0) {
            $this->w($L, 'public function __construct(' . $this->emitParamList($params) . ") {");
            $this->indent++;
            $this->pushScope();
            $prevRet = $this->curRet;
            $this->curRet = null;
            $this->emitPrologue($params, '__construct', $L);
            foreach ($ctorBody as $line) { $this->w($L, $line); }
            if ($hasCtor && $ctorHasBody) {
                foreach ($ctorBodyStmts['stmts'] as $st) { $this->emitStmt($st, $L); }
            }
            $this->curRet = $prevRet;
            $this->popScope();
            $this->indent--;
            $this->w($L, '}');
        }

        // __str__ -> also provide __toString for pyhp_tostr()
        if ($strMethod !== null) {
            $this->emitMethod($strMethod, $L);
            $this->w($L, 'public function __toString(): string { return $this->' . $strMethod['name'] . '(); }');
        }

        $this->curClass = null;
        $this->indent--;
        $this->w($L, '}');
        $this->w($L, '');
    }

    /** Property default expressions are evaluated in an empty scope. */
    private function emitExprScopeIsolated(array $e): string {
        $this->pushScope();
        $code = $this->emitExpr($e);
        $this->popScope();
        return $code;
    }

    private function emitMethod(array $m, array &$L): void {
        if (pyhp_ast_has_yield($m['body']['stmts'])) {
            // generator method: PHP closures inside methods bind $this automatically
            $this->w($L, 'public function ' . $m['name'] . '(' . $this->emitParamList($m['params']) . ') {');
            $this->indent++;
            $this->pushScope();
            $prevRet = $this->curRet;
            $this->curRet = null;
            $savedTop = $this->atUnitTop;
            $this->atUnitTop = false;
            $this->emitPrologue($m['params'], $m['name'], $L);
            $params = $this->paramNames($m['params']);
            $this->w($L, 'return new PyHPGenerator((function () use (' . implode(', ', array_map(fn($v) => '$' . $v, $params)) . ') {');
            $this->indent++;
            $gd = $this->globalDecl($params);
            if ($gd !== null) { $this->w($L, $gd); }
            foreach ($m['body']['stmts'] as $st) { $this->emitStmt($st, $L); }
            $this->indent--;
            $this->w($L, "})(), " . var_export($m['name'], true) . ');');
            $this->atUnitTop = $savedTop;
            $this->curRet = $prevRet;
            $this->popScope();
            $this->indent--;
            $this->w($L, '}');
            return;
        }
        $this->w($L, 'public function ' . $m['name'] . '(' . $this->emitParamList($m['params']) . ') {');
        $this->indent++;
        $this->pushScope();
        $gd = $this->globalDecl($this->paramNames($m['params']));
        if ($gd !== null) { $this->w($L, $gd); }
        $prevRet = $this->curRet;
        $prevLabel = $this->curFnLabel;
        $this->curRet = $m['ret'];
        $this->curFnLabel = $m['name'];
        $savedTop = $this->atUnitTop;
        $this->atUnitTop = false;
        $this->emitPrologue($m['params'], $m['name'], $L);
        foreach ($m['body']['stmts'] as $st) { $this->emitStmt($st, $L); }
        $this->atUnitTop = $savedTop;
        if ($m['ret'] !== null) {
            $this->w($L, "return pyhp_check_type(null, '{$m['ret']}', '{$m['name']}() return');");
        }
        $this->curRet = $prevRet;
        $this->curFnLabel = $prevLabel;
        $this->popScope();
        $this->indent--;
        $this->w($L, '}');
    }

    /* ================================================================ */
    /* expression emission                                              */
    /* ================================================================ */

    private function emitExpr(array $e): string {
        switch ($e['k']) {
            case 'Num':
                return $e['v'] instanceof PyBigInt
                    ? 'pyhp_big(' . var_export($e['v']->dec, true) . ')'
                    : var_export($e['v'], true);
            case 'Str':
                return var_export($e['v'], true);
            case 'Bool':
                return $e['v'] ? 'true' : 'false';
            case 'Null':
                return 'null';
            case 'FStr': {
                $parts = [];
                foreach ($e['parts'] as $p) {
                    if ($p[0] === 's') { $parts[] = var_export($p[1], true); continue; }
                    $inner = $this->emitExpr($p[1]);
                    $parts[] = isset($p[2])
                        ? 'pyhp_format(' . $inner . ', ' . var_export($p[2], true) . ')'
                        : 'pyhp_tostr(' . $inner . ')';
                }
                return '(' . (implode(' . ', $parts) ?: "''") . ')';
            }
            case 'Var':
                // a top-level function referenced as a value becomes its callable name
                if ($this->funcKnown($e['name'])) {
                    $scope = $this->curScope();
                    if (!in_array($e['name'], $scope['assigned'], true)) {
                        return var_export($this->fnPhp($e['name']), true);
                    }
                }
                // native cpp export referenced as a value
                if (isset($this->cppExports[$e['name']])
                    && !in_array($e['name'], $this->curScope()['assigned'], true)) {
                    return "pyhp_cpp_fn(" . var_export($e['name'], true) . ")";
                }
                $unitRead = $this->unitVarRead($e['name']);
                if ($unitRead !== null) return $unitRead;
                return '$' . $e['name'];
            case 'This':
                return '$this';
            case 'List': {
                $items = array_map(fn($i) => $this->emitExpr($i), $e['items']);
                return 'new PyList([' . implode(', ', $items) . '])';
            }
            case 'Dict': {
                // flat [k, v, k, v, ...] list -> guarded pairs (big-int keys,
                // and any other key, pass through pyhp_guard_key like the interpreter)
                $flat = [];
                foreach ($e['pairs'] as [$pk, $pv]) {
                    $flat[] = $this->emitExpr($pk);
                    $flat[] = $this->emitExpr($pv);
                }
                return 'new PyDict(pyhp_dict_pairs([' . implode(', ', $flat) . ']))';
            }
            case 'Comp':
                return $this->emitComp($e);
            case 'Un': {
                $v = $this->emitExpr($e['e']);
                return match ($e['op']) {
                    '-' => "pyhp_neg({$v})",
                    '!', 'not' => "pyhp_not({$v})",
                    '~' => "pyhp_bitnot({$v})",
                };
            }
            case 'Post':
                return '(' . $this->emitPost($e) . ')';
            case 'Bin':
                return $this->emitBin($e);
            case 'Ternary':
                return '(pyhp_truthy(' . $this->emitExpr($e['c']) . ') ? ' . $this->emitExpr($e['a']) . ' : ' . $this->emitExpr($e['b']) . ')';
            case 'Idx':
                return 'pyhp_get(' . $this->emitExpr($e['obj']) . ', ' . $this->emitExpr($e['idx']) . ')';
            case 'Slice': {
                $s = $e['start'] === null ? 'null' : $this->emitExpr($e['start']);
                $t = $e['stop'] === null ? 'null' : $this->emitExpr($e['stop']);
                $st = $e['step'] === null ? 'null' : $this->emitExpr($e['step']);
                return 'pyhp_slice(' . $this->emitExpr($e['obj']) . ", {$s}, {$t}, {$st})";
            }
            case 'Member': {
                $name = $e['name'];
                if ($e['obj']['k'] === 'This') return "\$this->{$name}";
                return "pyhp_member(" . $this->emitExpr($e['obj']) . ', ' . var_export($name, true) . ')';
            }
            case 'Call':
                return $this->emitCall($e);
            case 'Yield':
                return 'yield' . ($e['e'] !== null ? ' (' . $this->emitExpr($e['e']) . ')' : '');
            case 'Func':
                return '(' . $this->emitClosure($e) . ')';
        }
        throw new PyHPSyntaxError("line {$e['line']}: unsupported expression '{$e['k']}' in compiled mode");
    }

    private function emitBin(array $e): string {
        $op = $e['op'];
        $l = $this->emitExpr($e['l']);
        $r = $this->emitExpr($e['r']);
        return match ($op) {
            '+' => "pyhp_add({$l}, {$r})",
            '-' => "pyhp_sub({$l}, {$r})",
            '*' => "pyhp_mul({$l}, {$r})",
            '/' => "pyhp_div({$l}, {$r})",
            '%' => "pyhp_mod({$l}, {$r})",
            '**' => "pyhp_pow({$l}, {$r})",
            '&' => "pyhp_bitand({$l}, {$r})",
            '|' => "pyhp_bitor({$l}, {$r})",
            '^' => "pyhp_bitxor({$l}, {$r})",
            '<<' => "pyhp_lshift({$l}, {$r})",
            '>>' => "pyhp_rshift({$l}, {$r})",
            '==' => "pyhp_eq({$l}, {$r})",
            '!=' => "!pyhp_eq({$l}, {$r})",
            '<' => "(pyhp_compare({$l}, {$r}) < 0)",
            '<=' => "(pyhp_compare({$l}, {$r}) <= 0)",
            '>' => "(pyhp_compare({$l}, {$r}) > 0)",
            '>=' => "(pyhp_compare({$l}, {$r}) >= 0)",
            'in' => "pyhp_in({$l}, {$r})",
            'notin' => "!pyhp_in({$l}, {$r})",
            'and', 'or' => $this->emitLogic($op, $l, $r),
            ',' => "{$l}, {$r}",
            default => throw new PyHPSyntaxError("line {$e['line']}: unknown operator '{$op}'"),
        };
    }

    /** Value-preserving short-circuit and/or (Python semantics). */
    private function emitLogic(string $op, string $l, string $r): string {
        $t = $this->tmp();
        if ($op === 'and') {
            return "(pyhp_truthy({$t} = {$l}) ? {$r} : {$t})";
        }
        return "(pyhp_truthy({$t} = {$l}) ? {$t} : {$r})";
    }

    private function emitComp(array $e): string {
        $two = $e['var2'] !== null;
        $vars = $two ? [$e['var1'], $e['var2']] : [$e['var1']];
        $captures = array_values(array_diff($this->assignedSoFar(), $vars));
        $use = count($captures) > 0 ? ' use (' . implode(', ', array_map(fn($c) => '&$' . $c, $captures)) . ')' : '';
        $paramSig = $two ? '$' . $e['var1'] . ', $' . $e['var2'] : '$' . $e['var1'];

        // body scope for inner expressions
        $this->pushScope();
        foreach ($vars as $v) { $this->markAssigned($v); }
        $valCode = $this->emitExpr($e['val']);
        $condCode = $e['cond'] !== null ? $this->emitExpr($e['cond']) : null;
        if ($e['isDict']) {
            $keyCode = $this->emitExpr($e['key']);
            $pair = "new PyList([{$keyCode}, {$valCode}])";
            $this->popScope();
            $condArg = $condCode === null ? 'null' : "function ({$paramSig}){$use} { return {$condCode}; }";
            return "pyhp_dictcomp(function ({$paramSig}){$use} { return {$pair}; }, {$condArg}, " . $this->emitExpr($e['iter']) . ', ' . ($two ? 'true' : 'false') . ')';
        }
        $this->popScope();
        $condArg = $condCode === null ? 'null' : "function ({$paramSig}){$use} { return {$condCode}; }";
        return "pyhp_listcomp(function ({$paramSig}){$use} { return {$valCode}; }, {$condArg}, " . $this->emitExpr($e['iter']) . ', ' . ($two ? 'true' : 'false') . ')';
    }

    private function emitCallArgs(array $args): string {
        return implode(', ', array_map(fn($a) => $this->emitExpr($a), $args));
    }

    /* ---------------- modules ---------------- */

    /** Compile `require("<spec>")`: resolve, transpile the module in its own
     *  namespace, emit it into the pending buffer, and return a call to a
     *  module-init function that builds (and caches) the export table. */
    private function emitRequire(array $e): string {
        $args = $e['args'];
        if (count($args) !== 1) {
            throw new PyHPSyntaxError("line {$e['line']}: require() takes exactly 1 argument(s), got " . count($args));
        }
        $a = $args[0];
        if ($a['k'] !== 'Str') {
            throw new PyHPSyntaxError("line {$e['line']}: require() takes a literal module name or path in compiled mode");
        }
        $spec = $a['v'];
        $base = $this->sourceDir ?? (getcwd() ?: '.');
        $path = pyhp_resolve_module($spec, $base);
        if ($path === null) {
            throw new PyHPSyntaxError("line {$e['line']}: ModuleNotFoundError: cannot find module '{$spec}' (looked in ./vendor and the registry)");
        }
        $id = $this->compileModule($path, $spec, $e['line']);
        return 'pyhp_module_' . $id . '()';
    }

    /** Compile a module unit once (cached by realpath). Registering the id
     *  before compiling the body is what makes circular requires detectable
     *  and lets `extends` resolve parents across modules on demand. */
    private function compileModule(string $path, string $spec, int $line): string {
        if (isset($this->modCache[$path])) {
            return $this->modCache[$path];
        }
        if (in_array($path, $this->modStack, true)) {
            throw new PyHPSyntaxError("circular module dependency: '{$spec}'");
        }
        $id = 'm' . count($this->modCache);
        $this->modCache[$path] = $id;

        $src = file_get_contents($path);
        $stmts = PyHPParser::parseSource($src);
        [$funcNames, $lambdaNames, $classNames] = $this->moduleExportNames($stmts);

        $savedNs = $this->ns;
        $savedDir = $this->sourceDir;
        $savedIndent = $this->indent;
        $savedTop = $this->atUnitTop;
        $this->ns = $id . '_';
        $this->sourceDir = dirname($path);
        $this->modStack[] = $path;
        $this->atUnitTop = false;
        $this->unitVars[$id . '_'] = $this->collectUnitVars($stmts);

        // collect the module's own funcs/classes, then resolve property types
        $this->prePassStmts($stmts, true);
        foreach ($this->modClasses[$this->ns] ?? [] as $name => $def) {
            $chain = [];
            $c = $name;
            while ($c !== null && isset($this->modClasses[$this->ns][$c])) {
                array_unshift($chain, $c);
                $c = $this->modClasses[$this->ns][$c]['ext'];
            }
            $resolved = [];
            foreach ($chain as $cn) {
                foreach ($this->modPropTypes[$this->ns][$cn] ?? [] as $p => $t) { $resolved[$p] = $t; }
            }
            $this->modPropTypes[$this->ns][$name] = $resolved;
        }

        // function/class definitions are hoisted to file scope
        $buf = [];
        foreach ($stmts as $s) {
            if ($s['k'] === 'Func' && $s['name'] !== null) $this->emitTopFunction($s, $buf);
            elseif ($s['k'] === 'Class') $this->emitClass($s, $buf);
        }

        // init function: run top-level statements once, then build the table
        $this->indent = 1;
        $this->pushScope();
        $this->w($buf, 'function pyhp_module_' . $id . '() {');
        $this->indent = 2;
        $this->w($buf, 'static $m = null;');
        $this->w($buf, 'if ($m !== null) { return $m; }');
        $this->atUnitTop = true;   // these statements ARE the module's top level
        foreach ($stmts as $s) {
            if ($s['k'] === 'Func' && $s['name'] !== null) continue; // hoisted above
            if ($s['k'] === 'Class') continue;                       // hoisted above
            $this->emitStmt($s, $buf);
        }
        $this->atUnitTop = false;
        $entries = [];
        foreach ($funcNames as $n) {
            $entries[] = var_export($n, true) . ' => fn(...$__a) => ' . $this->fnPhp($n) . '(...$__a)';
        }
        foreach ($lambdaNames as $n) {
            if (isset($this->unitVars[$id . '_'][$n])) {
                // unit-level lambda: its value lives in the module state bucket
                $entries[] = var_export($n, true) . ' => fn(...$__a) => pyhp_unit_get('
                    . var_export($id, true) . ', ' . var_export($n, true) . ')(...$__a)';
            } else {
                // lambdas live in local vars of this init function; arrow fns capture by value
                $entries[] = var_export($n, true) . ' => fn(...$__a) => $' . $n . '(...$__a)';
            }
        }
        foreach ($classNames as $n) {
            $entries[] = var_export($n, true) . ' => fn(...$__a) => new ' . $this->clsPhp($n) . '(...$__a)';
        }
        $this->w($buf, '$m = new PyDict([' . implode(', ', $entries) . ']);');
        $this->w($buf, 'return $m;');
        $this->indent = 1;
        $this->w($buf, '}');
        $this->w($buf, '');
        $this->popScope();
        $this->pendingMods[] = implode("\n", $buf);

        array_pop($this->modStack);
        $this->sourceDir = $savedDir;
        $this->ns = $savedNs;
        $this->indent = $savedIndent;
        $this->atUnitTop = $savedTop;
        return $id;
    }

    /** Static scan of a module AST: exported names = named top-level functions,
     *  top-level lambda assignments, and top-level classes. */
    private function moduleExportNames(array $stmts): array {
        $funcs = [];
        $lambdas = [];
        $classes = [];
        foreach ($stmts as $s) {
            if ($s['k'] === 'Func' && $s['name'] !== null) {
                $funcs[] = $s['name'];
            } elseif ($s['k'] === 'Expr' && $s['e']['k'] === 'Assign'
                && $s['e']['target']['k'] === 'Var' && $s['e']['value']['k'] === 'Func') {
                $lambdas[] = $s['e']['target']['name'];
            } elseif ($s['k'] === 'VarDecl' && $s['init'] !== null && $s['init']['k'] === 'Func') {
                $lambdas[] = $s['name'];
            } elseif ($s['k'] === 'Class') {
                $classes[] = $s['name'];
            }
        }
        return [$funcs, $lambdas, $classes];
    }

    private function emitCall(array $e): string {
        $callee = $e['callee'];
        $kws = $e['kwargs'] ?? [];
        $posList = '[' . $this->emitCallArgs($e['args']) . ']';
        $kwList = '[' . implode(', ', array_map(
            fn($kw) => "['name' => " . var_export($kw['name'], true) . ", 'value' => " . $this->emitExpr($kw['expr']) . ']',
            $kws)) . ']';
        if ($callee['k'] === 'Super') {
            if (count($kws) > 0) {
                return "pyhp_call_kw_parent(\$this, '__construct', {$posList}, {$kwList}, '__construct')";
            }
            return 'parent::__construct(' . $this->emitCallArgs($e['args']) . ')';
        }
        if ($callee['k'] === 'Member' && $callee['obj']['k'] === 'Super') {
            if (count($kws) > 0) {
                return 'pyhp_call_kw_parent($this, ' . var_export($callee['name'], true) . ", {$posList}, {$kwList}, " . var_export($callee['name'], true) . ')';
            }
            return 'parent::' . $callee['name'] . '(' . $this->emitCallArgs($e['args']) . ')';
        }
        if ($callee['k'] === 'Member' && $callee['obj']['k'] === 'This') {
            if (count($kws) > 0) {
                return 'pyhp_call_kw_method($this, ' . var_export($callee['name'], true) . ", {$posList}, {$kwList}, " . var_export($callee['name'], true) . ')';
            }
            return '$this->' . $callee['name'] . '(' . $this->emitCallArgs($e['args']) . ')';
        }
        if ($callee['k'] === 'Member') {
            $obj = $this->emitExpr($callee['obj']);
            // pyhp_call_method binds kwargs via reflection for transpiled user
            // classes; plain positional calls keep the fast path
            return "pyhp_call_method({$obj}, " . var_export($callee['name'], true) . ", {$posList}, {$kwList})";
        }
        if ($callee['k'] === 'Var') {
            $name = $callee['name'];
            $scope = $this->curScope();
            $map = pyhp_error_class_map();
            if (in_array($name, $scope['assigned'], true)) {
                if (count($kws) > 0) {
                    return "pyhp_call_kw(\${$name}, {$posList}, {$kwList}, " . var_export($name, true) . ')';
                }
                return "pyhp_callfunc(\${$name}, [" . $this->emitCallArgs($e['args']) . "], " . var_export($name, true) . ')';
            }
            if ($name === 'require') {
                return $this->emitRequire($e);
            }
            $unitCall = $this->unitVarRead($name);
            if ($unitCall !== null) {
                if (count($kws) > 0) {
                    return "pyhp_call_kw({$unitCall}, {$posList}, {$kwList}, " . var_export($name, true) . ')';
                }
                return "pyhp_callfunc({$unitCall}, [" . $this->emitCallArgs($e['args']) . "], " . var_export($name, true) . ')';
            }
            if ($this->funcKnown($name)) {
                if (count($kws) > 0) {
                    return 'pyhp_call_kw(' . var_export($this->fnPhp($name), true) . ", {$posList}, {$kwList}, " . var_export($name, true) . ')';
                }
                return $this->fnPhp($name) . '(' . $this->emitCallArgs($e['args']) . ')';
            }
            if ($this->clsKnown($name)) {
                if (count($kws) > 0) {
                    return 'pyhp_new_kw(' . var_export($this->clsPhp($name), true) . ", {$posList}, {$kwList}, " . var_export($name, true) . ')';
                }
                return 'new ' . $this->clsPhp($name) . '(' . $this->emitCallArgs($e['args']) . ')';
            }
            if (isset($this->cppExports[$name])) {
                if (count($kws) > 0) {
                    throw new PyHPSyntaxError("line {$e['line']}: native cpp exports accept positional arguments only");
                }
                return "pyhp_cpp_call(" . var_export($name, true) . ', [' . $this->emitCallArgs($e['args']) . '])';
            }
            if (isset($map[$name])) {
                if (count($kws) > 0) {
                    throw new PyHPSyntaxError("line {$e['line']}: error classes accept positional arguments only");
                }
                return 'new ' . $map[$name] . '(' . $this->emitCallArgs($e['args']) . ')';
            }
            if (pyhp_builtin_exists($name)) {
                if (count($kws) > 0) {
                    return 'pyhp_call_builtin(' . var_export($name, true) . ", {$posList}, {$kwList})";
                }
                return "pyhp_fn_call(" . var_export($name, true) . ', ' . $this->emitCallArgs($e['args']) . ')';
            }
            if (count($kws) > 0) {
                return "pyhp_call_kw(\${$name}, {$posList}, {$kwList}, " . var_export($name, true) . ')';
            }
            return "pyhp_callfunc(\${$name}, [" . $this->emitCallArgs($e['args']) . "], " . var_export($name, true) . ')';
        }
        if (count($kws) > 0) {
            return 'pyhp_call_kw(' . $this->emitExpr($callee) . ", {$posList}, {$kwList}, '<expression>')";
        }
        return 'pyhp_callfunc(' . $this->emitExpr($callee) . ', [' . $this->emitCallArgs($e['args']) . "], '<expression>')";
    }
}
